        getFunc = function() return YeOldeLootHistory.SV.ContainerShowTime end,
        setFunc = function(value)
            YeOldeLootHistory.SV.ContainerShowTime = value
            YeOldeLootHistory.UpdateContainerShowTime()
        end,
        min = 1000,
        max = 10000,
        step = 500,
        decimals = 0,
    }
    optionsTable[#optionsTable + 1] = {
        type = "slider",
