        end,
        min = 1000,
        max = 10000,
        step = 500,
        decimals = 0,
    }
    optionsTable[#optionsTable + 1] = {
        type = "slider",
        name = YeOldeLootHistory.lang[SI_YEOLDEHISTORYLOOT_MAX_ITEMS],
        getFunc = function() return YeOldeLootHistory.SV.MaxItems end,
        setFunc = function(value)
            YeOldeLootHistory.SV.MaxItems = value
            YeOldeLootHistory.UpdateMaxEntries()
        end,
        min = 2,
        max = 20,
        step = 1,
        decimals = 0,
    }
    optionsTable[#optionsTable + 1] = {
        type = "checkbox",
        name = YeOldeLootHistory.lang[SI_YEOLDEHISTORYLOOT_SHOW_IN_MENU],
        getFunc = function() return YeOldeLootHistory.SV.ShowInMenus end,
