        local skillLineData = SKILLS_DATA_MANAGER:GetSkillLineDataByIndices(SKILL_TYPE_WORLD, skillIndex)

        optionsTable[#optionsTable + 1] = {
            type = "checkbox",
            name = skillLineData:GetFormattedName(),
            getFunc = function() return YeOldeLootHistory.SV.ShowType[skillIndex] end,
            setFunc = function(value) YeOldeLootHistory.SV.ShowType[skillIndex] = value end,
        }
    end

    optionsTable[#optionsTable + 1] = {
        type = "divider",
        reference = CreateRef(#optionsTable),
    }
    optionsTable[#optionsTable + 1] = {
        type = "description",
        title = SetTitle(SI_YEOLDEHISTORYLOOT_DEBUG_OPTIONS),
        reference = CreateRef(#optionsTable),
    }
    optionsTable[#optionsTable + 1] = {
        type = "checkbox",
        name = YeOldeLootHistory.lang[SI_YEOLDEHISTORYLOOT_DEBUG_ENABLED],
        getFunc = function() return YeOldeLootHistory.SV.DebugEnabled end,
        setFunc = function(value) YeOldeLootHistory.SV.DebugEnabled = value end,
    }

