    local LAM = LibAddonMenu2
    LAM:RegisterAddonPanel("YeOldeLootHistoryMenu", panelData)
    LAM:RegisterOptionControls("YeOldeLootHistoryMenu", optionsTable)
end

function YeOldeLootHistory.Initialize(eventCode, addOnName)
    if (addOnName ~= "YeOldeLootHistory") then return end
    YeOldeLootHistory.SV = ZO_SavedVars:NewAccountWide("YeOldeLootHistoryVars", 1.0, nil, YeOldeLootHistory.DefaultValues, nil)

    LootHistoryExt_Load()

    YeOldeLootHistory.CreateSettingsMenu()
end

EVENT_MANAGER:RegisterForEvent(YeOldeLootHistory.AddonName, EVENT_ADD_ON_LOADED, YeOldeLootHistory.Initialize)


